import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const read=f=>fs.readFileSync(path.join(root,f));
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const json=f=>JSON.parse(read(f).toString('utf8').replace(/^\uFEFF/,''));
const pin=f=>{const b=read(f);return {path:f,size:b.length,sha256:sha(b)};};
const prefix='docs/evidence/d-resources-rules-local-74489207adda4f9fa60c2605ccc18233';
const request='docs/evidence/d-resources-sql-review-request-20261023.json';
const r=json(request), source=json(prefix+'-source.json'), receipt=json(prefix+'.json');
assert.equal(r.source_files.length,153);assert.equal(receipt.exit_code,0);assert.equal(receipt.error,null);
for(const key of ['frozen_inputs_stable','current_inputs_stable','owner_removed','default_vet'])assert.equal(receipt[key],true);
for(const key of ['dependencies_installed','actual_mysql','production_wired'])assert.equal(receipt[key],false);
assert.equal(path.dirname(path.resolve(receipt.owner)),root);
assert.equal(path.basename(receipt.owner),'.tmp-d-resources-rules-74489207adda4f9fa60c2605ccc18233');
assert.equal(fs.existsSync(receipt.owner),false);
for(const p of source.inputs){const b=Buffer.from(p.bytes_base64,'base64');assert.equal(b.length,p.size);assert.equal(sha(b),p.sha256);assert.equal(sha(read(p.path)),p.sha256);}
for(const p of r.source_files)assert.deepEqual(pin(p.path),p);
const events=read(prefix+'.jsonl').toString('utf8').replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean).map(JSON.parse);
assert.equal(events.filter(e=>['fail','skip'].includes(e.Action)).length,0);
const starts=events.filter(e=>e.Action==='start'), ends=events.filter(e=>e.Action==='pass'&&!e.Test);
assert.equal(starts.length,1);assert.equal(ends.length,1);
const frozenPackage='_/'+receipt.owner.replaceAll('\\','/').replace(':','_')+'/source/backend/internal/systembackupresources';
assert.equal(starts[0].Package,frozenPackage);assert.ok(events.every(e=>e.Package===frozenPackage));
assert.equal(events.at(-1).Action,'pass');assert.equal(events.at(-1).Test,undefined);
const passes=events.filter(e=>e.Action==='pass'&&e.Test),runs=events.filter(e=>e.Action==='run'&&e.Test);
assert.equal(passes.length,388);assert.equal(new Set(passes.map(e=>e.Test)).size,388);
assert.deepEqual(runs.map(e=>e.Test).sort(),passes.map(e=>e.Test).sort());
assert.equal(passes.filter(e=>!e.Test.includes('/')).length,42);
assert.equal(passes.filter(e=>e.Test.startsWith('TestRestoreFieldsSQLFailuresDiscardAllRows/')).length,16);
assert.equal(passes.filter(e=>e.Test.startsWith('TestRestoreFieldsEveryColumn/')).length,111);
const output='docs/evidence/a-resources-sql-reviewed-20261023.json';
const result={kind:'a_resources_sql_reader_incremental_review.v1',date:'2026-10-23',status:'private_candidate_and_frozen_synthetic_tests_accepted',request:pin(request),source_digest:r.source_digest,request_inputs:r.source_files.length,frozen_inputs:source.inputs.length,evidence:[prefix+'.json',prefix+'.jsonl',prefix+'-source.json','docs/evidence/d-resources-sql-validation-20261023.json','docs/system-backup-a-resources-sql-review-20261023.md','docs/evidence/a-resources-sql-review-20261023.mjs'].map(pin),roots:42,pass_events:388,negative_paths:16,column_mutations:111,default_vet:true,owner:receipt.owner,cleanup_verified:true,reviewer_go_run:false,actual_mysql:false,production_approved:false,current_whole_package_accepted:false,complete_normalization:false};
if(process.argv.includes('--write'))fs.writeFileSync(path.join(root,output),JSON.stringify(result,null,2)+'\n',{flag:'wx'});
else {assert.ok(process.argv.includes('--check'));assert.deepEqual(json(output),result);}
console.log('A_SQL_READER_REVIEW roots=42 passes=388 synthetic_only=yes production=no');
